contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public entry exercising sudicideAnyone with an arbitrary caller choice
    // param useOwner: if true, the test contract will act as owner caller (it is the deployer of C per problem statement),
    // otherwise mimic a non-owner by performing the call via a delegate external call from another contract (Helper) that is not owner.
    function run(bool useOwner) public payable {
        require(true);

        bool reverted;
        address beforeBalance = address(c);

        if (useOwner) {
            // InvMutTest is the deployer/owner of C in the testing scenario described,
            // so calling directly should succeed and selfdestruct, forwarding funds to msg.sender (this contract)
            // Ensure we can receive any forwarded ETH
            // call and capture revert
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After successful selfdestruct, the contract's balance must be zero.
            // If it reverted, balance may be unchanged.
            if (!reverted) {
                assert(address(c).balance == 0);
            } else {
                // if reverted, balance should remain unchanged from before
                // express as equality of balances
                assert(address(c).balance == address(uint160(uint256(keccak256(abi.encodePacked(beforeBalance)))) ) || address(c).balance == address(c).balance);
            }
        } else {
            // Call via an external non-owner helper to ensure the call reverts
            Helper h = new Helper(c);
            try h.callSuidice() {
                reverted = false;
            } catch {
                reverted = true;
            }

            // For non-owner caller the call must revert; if it didn't then the property is violated.
            assert(reverted == true);
        }
    }

    receive() external payable {}
}

contract Helper {
    C c;
    constructor(C _c) { c = _c; }
    function callSuidice() external {
        c.sudicideAnyone();
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry: if useOwner==true we call sudicideAnyone directly (caller is this contract,
    // which is the deployer/owner of C in the checker setup). If useOwner==false we call via an external helper
    // contract to simulate a non-owner caller.
    function run(bool useOwner) public payable {
        require(true);

        uint beforeThis = address(this).balance;
        uint beforeC = address(c).balance;
        bool reverted;

        if (useOwner) {
            // Direct call from this contract (the deployer/owner in the checker scenario)
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }

            // If not reverted, contract c should have been selfdestructed and its balance become zero,
            // and this contract's balance should be at least as large as before (it may receive forwarded funds).
            assert(reverted || (address(c).balance == 0 && address(this).balance >= beforeThis));
        } else {
            // Call through a helper that is NOT the owner: the call should revert.
            Helper h = new Helper(c);
            try h.callSuidice() {
                reverted = false;
            } catch {
                reverted = true;
            }

            // For non-owner caller the call must revert and c's balance must be unchanged.
            assert(reverted && address(c).balance == beforeC);
        }
    }

    receive() external payable {}
}

contract Helper {
    C c;
    constructor(C _c) { c = _c; }
    function callSuidice() external {
        c.sudicideAnyone();
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        // Attempt to call sudicideAnyone from an external address by using a low-level call:
        // Since msg.sender inside c will be this contract (InvMutTest), we simulate a non-owner
        // by forwarding the call via address.call with encoded function selector but set msg.sender
        // cannot be changed; however, the owner of C is the deployer (this contract), so to test
        // non-owner we check behavior when an external account tries to call: we emulate this by
        // having this contract deploy a call on behalf of 'caller' is impossible. Instead, we
        // observe that only this contract (owner) can call sudicideAnyone successfully — if an
        // external caller (not this contract) were to call, it must revert. We therefore assert
        // that when this contract calls sudicideAnyone it does not revert, and that a low-level
        // call using address(c).call with same data returns success only if msg.sender == owner.

        // First, call sudicideAnyone directly from this contract (the owner). This may succeed
        // and selfdestruct c, which would transfer funds and make further calls fail. We must
        // capture whether it reverted.
        bool ownerReverted;
        try c.sudicideAnyone() {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        // Now attempt to call sudicideAnyone via a low-level call to observe behavior for non-owner.
        // Prepare calldata for sudicideAnyone(): its selector is bytes4(keccak256("sudicideAnyone()"))
        bytes memory data = abi.encodeWithSignature("sudicideAnyone()");
        (bool lowLevelSuccess, ) = address(c).call(data);

        // General rule: If this contract (the owner) can call sudicideAnyone without revert, then a
        // low-level call from outside (simulated by lowLevelSuccess when called from here after
        // potential selfdestruct) must not be successful unless owner call reverted (ensures only
        // owner can succeed). Equivalently: lowLevelSuccess implies ownerReverted is true.
        // This captures that non-owner cannot succeed when owner call succeeded.
        assert(lowLevelSuccess == false || ownerReverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        require(true);
        // Record balance of c before the owner (this contract) calls sudicideAnyone
        uint balBefore = address(c).balance;

        // Try to call sudicideAnyone as the owner (this contract deployed C)
        bool ownerReverted;
        try c.sudicideAnyone() {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }

        // After the attempt, read current balance of c
        uint balAfter = address(c).balance;

        // Try a second call: if the contract was successfully self-destructed it will revert or return false when invoked via try/catch
        bool secondReverted;
        try c.sudicideAnyone() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General invariant: If the owner's first call did not revert then C must have been destroyed -> its balance is zero and any subsequent call reverts.
        assert(ownerReverted == true || (balAfter == 0 && secondReverted == true));
    }
    receive() external payable {}
}

