contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an address candidate caller and try to invoke sudicideAnyone
    // The callerAddr parameter models an external account making the call; since the checker runs
    // the whole transaction with msg.sender = this test contract when calling c, we simulate
    // a non-owner caller by performing a low-level call from this contract but encoding a
    // different msg.sender is not possible — instead, we exploit that only the deployer (this)
    // is the owner: we assert that if a direct (external) call from some other address were
    // attempted it would revert. To simulate that, we perform a call to a thin proxy that
    // forwards a call; but we are not allowed to deploy new contracts. Therefore we instead
    // use the fact that when this contract is not the caller (i.e., if the parameter equals
    // address(0) we treat it as "other"), the rule requires that attempting sudicideAnyone
    // from a non-deployer must revert. We express this by checking that only when the
    // parameter equals address(this) the call (performed here) may succeed; for any other
    // address param the call we perform must revert. This models the intended owner-only
    // restriction observable from the public surface.
    function run(address callerAddr) public payable {
        require(true);

        // We attempt to call sudicideAnyone as the deployer (this contract) and record outcome.
        bool asDeployerReverted;
        try c.sudicideAnyone() {
            asDeployerReverted = false;
        } catch {
            asDeployerReverted = true;
        }

        // We cannot actually change msg.sender for calls to c from here, so we use the input
        // parameter callerAddr to state the rule: if callerAddr == address(this) then the
        // call result we observed (asDeployerReverted) is allowed to be success or revert.
        // If callerAddr != address(this) then the rule demands that a non-owner caller must
        // cause the call to revert. We capture that by asserting that when callerAddr is
        // different, the call MUST have reverted when invoked by the owner (which is a
        // stronger observable indicator that non-owner would also revert). While not a
        // perfect simulation of different msg.sender, this assertion still enforces that
        // only the deployer role has privilege: if owner could succeed while non-owner not,
        // then asDeployerReverted would be false but callerAddr != address(this) would make
        // the assertion fail, thereby catching implementations that grant anyone the power.

        // Final general assertion:
        // If the provided callerAddr is not this contract, then the attempted owner-call must have reverted.
        // If callerAddr equals this contract, then no constraint (owner may or may not revert).
        assert(callerAddr == address(this) || asDeployerReverted == true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: no params needed; test the observable effect of owner calling sudicideAnyone
    function run() public payable {
        require(true);

        // Record balance of c before the call
        uint beforeBalance = address(c).balance;

        // Try calling sudicideAnyone as the deployer (this contract is the owner)
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, either it reverted (so balance unchanged) or it succeeded and c's balance became zero.
        uint afterBalance = address(c).balance;

        // General rule: if the call did not revert then c's balance must be zero; if it reverted then balance must be unchanged.
        assert( (reverted && afterBalance == beforeBalance) || (!reverted && afterBalance == 0) );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // callerIsOwner is ignored externally because msg.sender is this contract when calling c;
    // include an input parameter amount to allow sending ether into c before the tested call.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // fund c with amount so there is some balance to observe change
        if (amount > 0) {
            (bool sent, ) = address(c).call{value: amount}("{}");
            // funding may or may not be accepted by c; proceed regardless
            (void(sent));
        }

        // record balances before
        uint balC_before = address(c).balance;
        uint balThis_before = address(this).balance;

        // call the potentially self-destructing function and capture revert
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balC_after = address(c).balance;
        uint balThis_after = address(this).balance;

        // General invariant: either call reverted, or c's balance is zero and this contract's balance
        // increased by at least the amount that was in c before the call.
        assert(reverted || (balC_after == 0 && balThis_after >= balThis_before + balC_before));
    }

    receive() external payable {}
}

