contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = address(this); // this contract deployed c in the harness
    }

    // single public entry that checks the ownership restriction
    function run(address caller) public payable {
        require(caller != address(0));
        // We will attempt to call sudicideAnyone from either the owner (this contract)
        // or from a different caller by using low-level call simulation via the calldata
        // because we cannot change msg.sender when calling c directly. Instead we
        // observe that only this contract is the deployer/owner; so the property we assert
        // is: if the caller argument equals deployer then the call must NOT revert,
        // otherwise it MUST revert. We effect the two cases by having this contract
        // invoke sudicideAnyone and treating `caller` as the claimed caller in the assertion.

        // Make the state-affecting call: this contract (the owner) calls sudicideAnyone.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now assert the general rule relating the input 'caller' to whether the actual
        // call (from this contract) reverted. Since the harness deploys c, this contract
        // is the owner. Therefore if the provided caller equals deployer then the call
        // should not have reverted; if caller is some other address the call should
        // have reverted (because only owner may call). This links the parameter to
        // the contract's required access control behavior for all inputs.
        assert((caller == deployer) == (!reverted));
    }

    receive() external payable {}
}

