}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: include one parameter to range over
    function run(bool flag) public payable {
        // read code size before
        uint beforeCodeSize = address(c).code.length;

        bool reverted;
        // state-changing call must be a top-level statement
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterCodeSize = address(c).code.length;

        // General rule: for any boolean input, either the call reverted or the contract's code is gone
        assert(reverted || afterCodeSize == 0);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // callerIsOwner selects whether this test contract (the owner) will invoke sudicideAnyone or
    // whether we attempt the call from a simulated non-owner by using a call via address(c).call
    // with encoded selector; amount is unused but present to satisfy input requirements.
    function run(bool callerIsOwner, uint256 amount) public payable {
        require(true);
        // Ensure this contract has some Ether so selfdestruct could plausibly transfer value.
        // If callerIsOwner is true, we call c.sudicideAnyone() directly (msg.sender == deployer/owner).
        // If callerIsOwner is false, we attempt to call sudicideAnyone using low-level call from this contract
        // but with an altered msg.sender is not possible in EVM; instead we simulate a non-owner by
        // calling through address(c).call but this still originates from this contract. To create a non-owner
        // call we instead deploy that the owner is set to this contract at C construction (by problem statement),
        // so any other caller must revert. We therefore try to call c.sudicideAnyone using a try/catch where
        // the expectation is: if callerIsOwner == false then the call must revert.

        bool reverted;
        if (callerIsOwner) {
            // direct call as owner (this contract) — may or may not revert depending on selfdestruct semantics
            try c.sudicideAnyone() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Attempt to call sudicideAnyone but from a non-owner: we achieve this by creating a thin proxy
            // call using address(c).call with the selector, but sending it from this contract still. To actually
            // simulate a non-owner caller we instead use a low-level call to c from an external EOA would be needed,
            // which we cannot do here. However, we can observe that if any caller other than the owner attempts the call
            // it must revert; thus we assert that a call we make with an unrelated ABI-encoded call whose sender is this
            // contract but using a made-up from-address cannot change that. Since we cannot change msg.sender here,
            // we conservatively perform the low-level call and record whether it reverted — in environments where msg.sender
            // is not owner this should revert. For the property we assert that when callerIsOwner == false the call did revert.
            (bool ok, ) = address(c).call(abi.encodeWithSelector(bytes4(keccak256("sudicideAnyone()"))));
            reverted = !ok;
        }

        // The general rule: if callerIsOwner == false then the call must revert (i.e., only owner can succeed).
        assert((!callerIsOwner) ? reverted : true);
    }
    receive() external payable { }
}
